def test_replay_does_not_become_stale_or_conflict(self) -> None:
    # A later commit puts a concurrent (conflicting) record at g; the
    # replay verdict still comes solely from the request binding.
    conflicting = state(
        {"a": 1, "b": 1, "c": 1},
        {
            "k": record("v", False, {"a": 1}, "a"),
            "g": record("z", False, {"c": 1}, "c"),
        },
    )
    replication.apply_remote(
        self.path, request(rid="r2", base=self.s1, remote=conflicting)
    )
    again = replication.apply_remote(self.path, self.req)
    self.assertEqual(again["status"], "duplicate")
    self.assertEqual(
        {item["decision"] for item in again["items"]}, {"duplicate"}
    )

