    # A later commit makes one carried record stale and raises the
    # outer clock past the other record's prerequisite; the replay
    # verdict still comes solely from the request binding.
    advanced = state(
        {"a": 2, "b": 1},
        {
            "k": record("w", False, {"a": 2}, "a"),
            "g": record("w", False, {"b": 1}, "b"),
        },
    )
    r2 = replication.apply_remote(
        self.path, request(rid="r2", base=self.s1, remote=advanced)
    )
    self.assertEqual(r2["status"], "applied")
    again = replication.apply_remote(self.path, self.req)
    self.assertEqual(again["status"], "duplicate")
    self.assertEqual(
        {item["decision"] for item in again["items"]}, {"duplicate"}
    )
    self.assertTrue(all(item["need"] == {} for item in again["items"]))

